<?php
function create_order($pdo){$u=require_user($pdo);$i=json_body();require_fields($i,array('customer_name','phone','email','items'));require_valid_email($i['email']);if(!is_array($i['items'])||!$i['items'])error_response('Замовлення не містить товарів.',422);$qty=array();foreach($i['items']as$item){if(!isset($item['product_id'],$item['quantity'])||(int)$item['quantity']<1)error_response('Некоректна позиція замовлення.',422);$id=(int)$item['product_id'];$qty[$id]=(isset($qty[$id])?$qty[$id]:0)+(int)$item['quantity'];}$pdo->beginTransaction();try{$lines=array();$total=0;$q=$pdo->prepare('SELECT id,title,price,stock FROM products WHERE id=? FOR UPDATE');foreach($qty as$id=>$amount){$q->execute(array($id));$p=$q->fetch();if(!$p)throw new Exception('Товар не знайдено.');if((int)$p['stock']<$amount)throw new Exception('Недостатньо товару: '.$p['title'].'.');$total+=(float)$p['price']*$amount;$lines[]=array($p,$amount);}$pdo->prepare("INSERT INTO orders(user_id,customer_name,phone,email,comment,total_price,status) VALUES(?,?,?,?,?,?,'Нове')")->execute(array($u['id'],$i['customer_name'],$i['phone'],$i['email'],isset($i['comment'])?$i['comment']:null,$total));$orderId=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO order_items(order_id,product_id,quantity,price_at_purchase) VALUES(?,?,?,?)');$stock=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?');foreach($lines as$line){$ins->execute(array($orderId,$line[0]['id'],$line[1],$line[0]['price']));$stock->execute(array($line[1],$line[0]['id']));}$pdo->commit();}catch(Exception$e){if($pdo->inTransaction())$pdo->rollBack();error_response($e->getMessage(),422);}json_response(order_response($pdo,find_order($pdo,$orderId)),201);}
function list_orders($pdo){$a=authenticated_account($pdo);$sql='SELECT * FROM orders';$v=array();if($a['role']==='user'){$sql.=' WHERE user_id=?';$v[]=$a['data']['id'];}$s=$pdo->prepare($sql.' ORDER BY id DESC');$s->execute($v);$out=array();foreach($s->fetchAll()as$o)$out[]=order_response($pdo,$o);json_response($out);}
function show_order($pdo,$id){$a=authenticated_account($pdo);$o=find_order($pdo,$id);if($a['role']==='user'&&(int)$o['user_id']!==(int)$a['data']['id'])error_response('Немає доступу до цього замовлення.',403);json_response(order_response($pdo,$o));}
